from pathlib import Path
root=Path('experiments')
terms=['Bessel','exhaust','bounded-sums','bounded sums','Wright','Sait','Grothendieck','Dorofeev']
for path in root.rglob('*'):
 if path.is_file() and path.suffix in ('.md','.txt'):
  text=path.read_text(errors='ignore')
  matches=[line for line in text.splitlines() if any(t.lower() in line.lower() for t in terms)]
  if matches:
   print('\nFILE',path)
   print('\n'.join(matches)[:5500])

